        star_pt = np.array([np.float64(-4.95), np.float64(-0.35)] + [0.0])
        dist_h = [0.5305, 0.578, 0.6766, 0.8419, 1.1238, 1.6, 1.6, 1.1238, 0.8419, 0.6766, 0.578, 0.5305]
        area_h = [1.6, 1.6, 1.6, 1.5999, 1.5997, 1.5988, 1.5988, 1.5997, 1.5999, 1.6, 1.6, 1.6]
        ticks, per_tick = 12, 20
        colors = [TEAL, GOLD]
        pts = [np.array(p + [0.0]) for p in path]

        title = Text("Kepler's stopwatch", font_size=34, color=YELLOW).to_edge(UP, buff=0.25)
        orbit = VMobject(color=BLUE_D, stroke_width=2, stroke_opacity=0.6)
        orbit.set_points_as_corners(pts)
        star = Dot(star_pt, color=GOLD, radius=0.18)
        glow = Dot(star_pt, color=YELLOW, radius=0.32).set_opacity(0.25)

        # Two bar charts on the right: distance per tick and area per tick.
        def chart(base_y, label):
            axis = Line([1.0, base_y, 0], [6.7, base_y, 0], color=GREY_B, stroke_width=2)
            text = Text(label, font_size=22, color=GREY_A).next_to(axis, DOWN, buff=0.12)
            return VGroup(axis, text)

        dist_chart = chart(0.75, "distance travelled per tick")
        area_chart = chart(-2.45, "area swept per tick")
        bar_w = 5.4 / ticks

        idx = ValueTracker(0.0)

        def planet_pt():
            return pts[min(int(idx.get_value()), len(pts) - 1)]

        planet = always_redraw(lambda: Dot(planet_pt(), color=WHITE, radius=0.1))
        radius = always_redraw(lambda: Line(star_pt, planet_pt(), color=GREY_A, stroke_width=1.5))

        def wedge(k, opacity):
            return Polygon(star_pt, *pts[k * per_tick:(k + 1) * per_tick + 1],
                           color=colors[k % 2], fill_color=colors[k % 2],
                           fill_opacity=opacity, stroke_width=1)

        def growing():
            k = min(int(idx.get_value()) // per_tick, ticks - 1)
            j = int(idx.get_value())
            if j - k * per_tick < 2:
                return VMobject()
            return Polygon(star_pt, *pts[k * per_tick:j + 1], color=colors[k % 2],
                           fill_color=colors[k % 2], fill_opacity=0.25, stroke_width=1)

        current = always_redraw(growing)
        done = VGroup()

        def settle(group):
            # When a tick completes, freeze its wedge and add its two bars.
            k = len(group) // 4
            if k < ticks and idx.get_value() >= (k + 1) * per_tick:
                x = 1.0 + (k + 0.5) * bar_w
                c = colors[k % 2]
                group.add(wedge(k, 0.45))
                group.add(Dot(pts[(k + 1) * per_tick], color=c, radius=0.05))
                group.add(Rectangle(width=bar_w * 0.8, height=dist_h[k], fill_color=c,
                                    fill_opacity=0.85, stroke_width=0).move_to(
                                    [x, 0.75 + dist_h[k] / 2, 0]))
                group.add(Rectangle(width=bar_w * 0.8, height=area_h[k], fill_color=c,
                                    fill_opacity=0.85, stroke_width=0).move_to(
                                    [x, -2.45 + area_h[k] / 2, 0]))

        done.add_updater(settle)

        self.play(FadeIn(title), Create(orbit), FadeIn(glow), GrowFromCenter(star), run_time=1.2)
        self.play(FadeIn(dist_chart), FadeIn(area_chart), run_time=0.6)
        self.add(done, current, radius, planet)
        self.play(idx.animate.set_value(float(len(pts) - 1)), run_time=11.0, rate_func=linear)
        done.clear_updaters()
        current.clear_updaters()
        self.remove(current)
        dist_note = Text('distance per tick: fastest / slowest = 3.0×', font_size=22, color=ORANGE).move_to([3.85, 2.75, 0])
        area_note = Text('area per tick: all equal (within 0.1%)', font_size=22, color=GREEN_B).move_to([3.85, -0.45, 0])
        self.play(FadeIn(dist_note), FadeIn(area_note), run_time=0.8)
        self.wait(1.5)

        # AetherLab explanation layer: clear the stage, then explain what it showed.
        for _m in self.mobjects:
            _m.clear_updaters()
        if self.mobjects:
            self.play(FadeOut(*self.mobjects), run_time=0.8)
        _head = Text('What the animation shows', font_size=34, weight=BOLD, color=YELLOW)
        _eq = Text('dA/dt = L / (2m) = constant', font_size=28, color=WHITE)
        _facts = VGroup(Text('Orbit eccentricity e = 0.55', font_size=25, color=GREY_A), Text('Distance per tick varies 3.0× between the slowest and fastest ticks', font_size=25, color=GREY_A), Text('Area per tick: each wedge is 8.3% of the ellipse, equal within 0.1%', font_size=25, color=GREY_A)).arrange(DOWN, aligned_edge=LEFT, buff=0.3)
        _key = Text('The planet speeds up near the star and slows far away, but it always\nsweeps equal areas in equal times.', font_size=27, color=TEAL_A)
        _key_box = SurroundingRectangle(_key, color=TEAL, buff=0.22, corner_radius=0.12)
        _card = VGroup(_head, _eq, _facts, VGroup(_key, _key_box)).arrange(DOWN, buff=0.42)
        if _card.width > 12.4:
            _card.scale_to_fit_width(12.4)
        if _card.height > 7.0:
            _card.scale_to_fit_height(7.0)
        self.play(FadeIn(_head, shift=0.2 * DOWN), FadeIn(_eq), run_time=1.2)
        self.play(LaggedStart(*[FadeIn(_f, shift=0.2 * RIGHT) for _f in _facts], lag_ratio=0.85), run_time=4.2)
        self.play(FadeIn(_key), Create(_key_box), run_time=1.2)
        self.wait(4.2)
